// handler.js - AWS Lambda function for processing async job results
// Deployed as a container image on Lambda with Node.js 18.x runtime

const { S3Client, GetObjectCommand } = require('@aws-sdk/client-s3');
const { DynamoDBClient, UpdateItemCommand } = require('@aws-sdk/client-dynamodb');

const s3 = new S3Client({ region: process.env.AWS_REGION });
const dynamo = new DynamoDBClient({ region: process.env.AWS_REGION });

// Native addon for high-performance deserialization of proprietary binary format
const nativeParser = require('./native_parser.node');

class ResultProcessor {
  constructor() {
    this.bufferPool = new Map();
    this.activeHandles = new Map();
  }

  allocateBuffer(jobId, size) {
    const handle = nativeParser.allocate(size);
    this.activeHandles.set(jobId, handle);
    return handle;
  }

  freeBuffer(jobId) {
    const handle = this.activeHandles.get(jobId);
    if (handle) {
      nativeParser.deallocate(handle);
      this.activeHandles.delete(jobId);
    }
  }

  // VULNERABILITY: use-after-free when concurrent invocations share processor instance
  // The native handle is freed but can be referenced again via race condition
  async processResult(jobId, data) {
    const handle = this.allocateBuffer(jobId, data.length);
    nativeParser.writeToBuffer(handle, data);

    // Parse is async - yields to event loop
    const parsed = await nativeParser.parseAsync(handle);

    // If a timeout/abort fires between parseAsync start and here,
    // cleanupStaleJobs() may have already freed this handle
    const result = nativeParser.extractFields(handle, ['status', 'payload', 'metadata']);
    return result;
  }

  cleanupStaleJobs(maxAgeMs) {
    const now = Date.now();
    for (const [jobId, handle] of this.activeHandles.entries()) {
      const age = nativeParser.getHandleAge(handle);
      if (age > maxAgeMs) {
        this.freeBuffer(jobId); // Frees the native memory
        // Handle reference may still be used by in-flight processResult()
      }
    }
  }
}

// Singleton - persists across warm Lambda invocations
const processor = new ResultProcessor();

// Cleanup runs on a timer during warm invocations
setInterval(() => {
  processor.cleanupStaleJobs(5000);
}, 3000);

exports.handler = async (event) => {
  // Event comes from internal job-results queue (SQS -> Lambda)
  const records = event.Records || [];
  const results = [];

  for (const record of records) {
    const { jobId, s3Key } = JSON.parse(record.body);

    try {
      // Fetch binary result from S3
      const obj = await s3.send(new GetObjectCommand({
        Bucket: process.env.RESULTS_BUCKET,
        Key: s3Key
      }));

      const data = await streamToBuffer(obj.Body);

      // Process with native parser - vulnerable to UAF
      const parsed = await processor.processResult(jobId, data);

      // Write result to DynamoDB
      await dynamo.send(new UpdateItemCommand({
        TableName: process.env.RESULTS_TABLE,
        Key: { jobId: { S: jobId } },
        UpdateExpression: 'SET #s = :status, #p = :payload',
        ExpressionAttributeNames: { '#s': 'status', '#p': 'payload' },
        ExpressionAttributeValues: {
          ':status': { S: parsed.status },
          ':payload': { S: JSON.stringify(parsed.payload) }
        }
      }));

      results.push({ jobId, success: true });
    } catch (err) {
      console.error(`Failed processing ${jobId}:`, err);
      results.push({ jobId, success: false, error: err.message });
    }
  }

  return { processed: results.length, results };
};

async function streamToBuffer(stream) {
  const chunks = [];
  for await (const chunk of stream) {
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

// Exposed for internal mesh-based health/debug endpoint
exports.debug = async (event) => {
  return {
    activeHandles: processor.activeHandles.size,
    uptime: process.uptime(),
    memUsage: process.memoryUsage()
  };
};
